package com.novasoft.psicoapp.service;
import com.novasoft.psicoapp.model.User; import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.nio.charset.StandardCharsets; import java.security.Key; import java.util.Date;
@Service public class JwtService{ @Value("${app.jwt.secret}") private String secret; @Value("${app.jwt.expiration-minutes}") private long minutes; private Key key(){return Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));} public String generate(User u){Date now=new Date(); return Jwts.builder().subject(u.email).claim("role",u.role.name()).claim("name",u.name).issuedAt(now).expiration(new Date(now.getTime()+minutes*60_000)).signWith(key()).compact();} public String subject(String token){return Jwts.parser().verifyWith((javax.crypto.SecretKey)key()).build().parseSignedClaims(token).getPayload().getSubject();}}
